//! Numeric parity tests for the `androidx.graphics.shapes` port in
//! `internal/core/graphics/shapes/`.
//!
//! `tests/shapes/golden/*.json` are generated by running the vendored Kotlin
//! sources (pinned androidx commit 23327507f7fc7d5b19d65fec4b090f60c970079b)
//! through `tests/shapes/src/GoldenGenerator.kt`; every f32 is stored as its
//! IEEE-754 bit pattern. See `tests/shapes/golden/README.md` for the tolerance
//! policy: values produced without transcendental functions or square roots
//! must be bit-exact; everything else must be within 1e-4 (the JVM and the
//! no_std/libm targets may round the last ulp differently).

use i_slint_core::graphics::shapes::{self, CornerRounding, Morph, Point, RoundedPolygon};
use std::collections::BTreeMap;

const CENTER: Point = Point { x: 0.5, y: 0.5 };

fn cr(radius: f32) -> CornerRounding {
    CornerRounding::new(radius, 0.)
}

fn crs(radius: f32, smoothing: f32) -> CornerRounding {
    CornerRounding::new(radius, smoothing)
}

/// Port of `Matrix().apply { rotateZ(deg) }.map(point)` from
/// androidx.compose.ui.graphics: `r = deg * (PI / 180)` is computed in f64 and
/// `sin`/`cos` are narrowed to f32, matching the Kotlin implementation.
fn rotate_z(degrees: f32) -> impl Fn(f32, f32) -> Point {
    let r = degrees as f64 * (std::f64::consts::PI / 180.);
    let s = r.sin() as f32;
    let c = r.cos() as f32;
    move |x, y| Point { x: c * x - s * y, y: s * x + c * y }
}

fn scale(sx: f32, sy: f32) -> impl Fn(f32, f32) -> Point {
    move |x, y| Point { x: sx * x, y: sy * y }
}

fn custom(
    points: &[(f32, f32)],
    roundings: &[CornerRounding],
    reps: usize,
    mirroring: bool,
) -> RoundedPolygon {
    shapes::custom_polygon(points, roundings, CENTER, reps, mirroring).unwrap()
}

fn star(
    num_vertices_per_radius: usize,
    radius: f32,
    inner_radius: f32,
    rounding: CornerRounding,
    inner_rounding: Option<CornerRounding>,
) -> RoundedPolygon {
    shapes::star(
        num_vertices_per_radius,
        radius,
        inner_radius,
        rounding,
        inner_rounding,
        None,
        Point::ZERO,
    )
    .unwrap()
}

