// --- golden comparison helpers ------------------------------------------------

fn f32_bits(v: &serde_json::Value) -> f32 {
    f32::from_bits(v.as_u64().unwrap() as u32)
}

fn load_golden(name: &str) -> serde_json::Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../tests/shapes/golden/");
    serde_json::from_str(&std::fs::read_to_string(format!("{path}{name}")).unwrap()).unwrap()
}

struct Diff {
    mismatched_bits: usize,
    max_abs_diff: f32,
}

impl Diff {
    fn add(&mut self, expected: f32, actual: f32) {
        if expected.to_bits() != actual.to_bits() {
            self.mismatched_bits += 1;
            let d = (expected - actual).abs();
            if d > self.max_abs_diff {
                self.max_abs_diff = d;
            }
        }
    }
}

fn diff_cubics(expected: &serde_json::Value, actual: &[shapes::Cubic]) -> Diff {
    let mut diff = Diff { mismatched_bits: 0, max_abs_diff: 0. };
    let expected = expected.as_array().unwrap();
    assert_eq!(expected.len(), actual.len(), "cubic count mismatch");
    for (e, a) in expected.iter().zip(actual.iter()) {
        for (j, a) in a.points.iter().enumerate() {
            diff.add(f32_bits(&e[j]), *a);
        }
    }
    diff
}

fn assert_polygon_eq(name: &str, golden: &serde_json::Value, actual: &RoundedPolygon) {
    let diff = diff_cubics(&golden["cubics"], actual.cubics());
    // Tolerance: bit-exact is expected everywhere the computation has no
    // transcendental functions; those are allowed up to 1e-4 absolute.
    assert!(
        diff.max_abs_diff <= 1e-4,
        "{name}: {n} cubics differ by more than 1e-4 (max {d})",
        n = diff.mismatched_bits,
        d = diff.max_abs_diff
    );

    let center = golden["center"].as_array().unwrap();
    assert_eq!(f32_bits(&center[0]).to_bits(), actual.center_x().to_bits(), "{name}: centerX");
    assert_eq!(f32_bits(&center[1]).to_bits(), actual.center_y().to_bits(), "{name}: centerY");

    let bounds = golden["bounds"].as_array().unwrap();
    let actual_bounds = actual.calculate_bounds(true);
    for (i, b) in bounds.iter().enumerate() {
        assert!(
            (f32_bits(b) - actual_bounds[i]).abs() <= 1e-4,
            "{name}: bounds[{i}] expected {} got {}",
            f32_bits(b),
            actual_bounds[i]
        );
    }
    let max_bounds = golden["max_bounds"].as_array().unwrap();
    let actual_max_bounds = actual.calculate_max_bounds();
    for (i, b) in max_bounds.iter().enumerate() {
        assert!(
            (f32_bits(b) - actual_max_bounds[i]).abs() <= 1e-4,
            "{name}: max_bounds[{i}] expected {} got {}",
            f32_bits(b),
            actual_max_bounds[i]
        );
    }

    let features = golden["features"].as_array().unwrap();
    let actual_features = actual.features();
    assert_eq!(features.len(), actual_features.len(), "{name}: feature count");
    for (i, (f, a)) in features.iter().zip(actual_features.iter()).enumerate() {
        let (kind, convex, count) = match a {
            shapes::Feature::Edge(c) => ("edge", false, c.len()),
            shapes::Feature::Corner { cubics, convex } => ("corner", *convex, cubics.len()),
        };
        assert_eq!(f["kind"].as_str().unwrap(), kind, "{name}: feature {i} kind");
        assert_eq!(f["count"].as_u64().unwrap() as usize, count, "{name}: feature {i} cubic count");
        if kind == "corner" {
            assert_eq!(f["convex"].as_bool().unwrap(), convex, "{name}: feature {i} convex");
        }
    }
}

#[test]
fn material_shapes_parity() {
    let golden = load_golden("material_shapes.json");
    let shapes = golden["shapes"].as_object().unwrap();

    let actual: BTreeMap<_, _> = material::all()
        .into_iter()
        .chain(primitive_shapes())
        .map(|(n, p)| (n.to_string(), p))
        .collect();

    assert_eq!(shapes.len(), actual.len(), "shape count mismatch");
    for (name, golden_shape) in shapes {
        let polygon = actual.get(name).unwrap_or_else(|| panic!("missing shape {name}"));
        assert_polygon_eq(name, golden_shape, polygon);
    }
}

#[test]
fn morph_parity() {
    let golden = load_golden("morphs.json");
    let morphs = golden["morphs"].as_object().unwrap();

    let shapes: BTreeMap<_, _> = material::all().into_iter().collect();
    let built = |name: &str| -> RoundedPolygon {
        match name {
            "pill" => shapes::pill(2., 1., 0., Point::ZERO).unwrap(),
            "pill_star_8" => shapes::pill_star(
                2.,
                1.,
                8,
                0.5,
                CornerRounding::UNROUNDED,
                None,
                None,
                0.5,
                0.,
                Point::ZERO,
            )
            .unwrap(),
            _ => shapes
                .iter()
                .find_map(|(n, p)| (*n == name).then(|| p.clone()))
                .unwrap_or_else(|| panic!("missing shape {name}")),
        }
    };

    for (spec, progress_map) in morphs {
        let (from_name, to_name) = spec.split_once("->").unwrap();
        let morph = Morph::new(built(from_name), built(to_name));
        for (t_str, expected_cubics) in progress_map.as_object().unwrap() {
            let t: f32 = t_str.parse().unwrap();
            let cubics = morph.as_cubics(t);
            let diff = diff_cubics(expected_cubics, &cubics);
            assert!(
                diff.max_abs_diff <= 1e-4,
                "{spec} @ {t}: {n} cubics differ by more than 1e-4 (max {d})",
                n = diff.mismatched_bits,
                d = diff.max_abs_diff
            );
        }
    }
}
